import org.ruoyi.ipd.agent.kernel.ProjectAgentFoundationTools;public class GWebProbe{public static void main(String[]a){String r=ProjectAgentFoundationTools.webFetchTool().webFetch("https://www.rfc-editor.org/rfc/rfc9110.txt",500);System.out.println("PUBLIC_PRIMARY_FETCH_SUCCESS="+r.startsWith("status=200"));System.out.println("PUBLIC_FETCH_CHARS="+r.length());System.out.println("PUBLIC_RFC_MARKER="+r.contains("Internet Engineering Task Force"));System.out.println("TAVILY_KEY_PRESENT="+(System.getenv("TAVILY_API_KEY")!=null&&!System.getenv("TAVILY_API_KEY").isBlank()));String s=ProjectAgentFoundationTools.webSearchTool().webSearch("IETF HTTP Semantics RFC9110",1);System.out.println("WEB_SEARCH_PROVIDER_BLOCKED="+s.contains("TAVILY_API_KEY"));}}